+}
+.hero-card:hover { border-color: var(--text-3); transform: translateY(-2px); }
+.hero-card.featured { grid-column: 1 / -1; flex-direction: row; align-items: center; gap: 1.25rem; }
+
+.hero-card-img {
+  width: 100%;
+  aspect-ratio: 1;
+  background: var(--bg-hover);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 2.4rem;
+  flex-shrink: 0;
+}
+.hero-card.featured .hero-card-img { width: 80px; height: 80px; aspect-ratio: auto; font-size: 2rem; }
+
+.hero-card-name { font-size: .82rem; font-weight: 600; }
+.hero-card-price { font-size: .9rem; font-weight: 700; color: var(--accent); }
+.hero-card-rating { font-size: .72rem; color: var(--text-3); }
+
+/* ─── Section Scaffolding ──────────────────────────────────────── */
+.section { padding-block: 5rem; }
+.section + .section { border-top: 1px solid var(--border); }
+
+.section-header {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  margin-bottom: 2.25rem;
+  gap: 1rem;
+  flex-wrap: wrap;
+}
+
+.section-label {
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .12em;
+  text-transform: uppercase;
+  color: var(--accent);
+  margin-bottom: .35rem;
+}
+
+.section-title {
+  font-size: clamp(1.4rem, 3vw, 2rem);
+  font-weight: 800;
+  letter-spacing: -.02em;
+}
+
+.section-sub {
+  font-size: .9rem;
+  color: var(--text-2);
+  margin-top: .3rem;
+}
+
+.view-all {
+  display: inline-flex;
+  align-items: center;
+  gap: .35rem;
+  font-size: .85rem;
+  font-weight: 600;
+  color: var(--accent);
+  white-space: nowrap;
+  transition: gap var(--transition);
+}
+.view-all:hover { gap: .6rem; }
+
+/* ─── Categories ───────────────────────────────────────────────── */
+.categories-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
+  gap: .85rem;
+}
+
+.category-card {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  padding: 1.4rem 1rem;
+  text-align: center;
+  cursor: pointer;
+  transition: all var(--transition);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .7rem;
+}
+.category-card:hover {
+  border-color: var(--accent);
+  background: var(--bg-hover);
+  transform: translateY(-2px);
+}
+
+.category-icon {
+  width: 52px;
+  height: 52px;
+  border-radius: var(--radius-sm);
+  background: var(--bg-hover);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 1.6rem;
+  transition: background var(--transition);
+}
+.category-card:hover .category-icon { background: var(--accent-glow); }
+
+.category-name {
+  font-size: .8rem;
+  font-weight: 600;
+  color: var(--text-2);
+}
+.category-count {
+  font-size: .7rem;
+  color: var(--text-3);
+}
+
+/* ─── Product Grid ─────────────────────────────────────────────── */
+.products-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 1.25rem;
+}
+
+.product-card {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  transition: all var(--transition);
+  display: flex;
+  flex-direction: column;
+  position: relative;
+}
+.product-card:hover {
+  border-color: var(--text-3);
+  transform: translateY(-3px);
+  box-shadow: var(--shadow-card);
+}
+
+.product-img {
+  aspect-ratio: 1 / 1;
+  background: var(--bg-hover);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 3.5rem;
+  position: relative;
+  overflow: hidden;
+}
+
+.product-badges {
+  position: absolute;
+  top: .75rem;
+  left: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .35rem;
+}
+
+.badge {
+  font-size: .68rem;
+  font-weight: 700;
+  letter-spacing: .04em;
+  padding: .2rem .55rem;
+  border-radius: 99px;
+  text-transform: uppercase;
+}
+.badge-new    { background: #4a90e8; color: #fff; }
+.badge-sale   { background: var(--red); color: #fff; }
+.badge-hot    { background: #e87a4a; color: #fff; }
+.badge-sold   { background: var(--text-3); color: var(--bg-base); }
+
+.product-wishlist {
+  position: absolute;
+  top: .75rem;
+  right: .75rem;
+  width: 32px;
+  height: 32px;
+  background: rgba(13,13,15,.7);
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--text-3);
+  transition: all var(--transition);
+  opacity: 0;
+}
+.product-card:hover .product-wishlist { opacity: 1; }
+.product-wishlist:hover { color: var(--red); background: rgba(232,84,84,.15); }
+.product-wishlist.active { opacity: 1; color: var(--red); }
+
+.product-body {
+  padding: 1rem 1.1rem 1.2rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  gap: .35rem;
+}
+
+.product-brand {
+  font-size: .7rem;
+  font-weight: 600;
+  color: var(--text-3);
+  text-transform: uppercase;
+  letter-spacing: .06em;
+}
+
+.product-name {
+  font-size: .9rem;
+  font-weight: 600;
+  color: var(--text-1);
+  line-height: 1.4;
+}
+
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: .35rem;
+  margin-top: .1rem;
+}
+.stars { color: var(--accent); font-size: .78rem; letter-spacing: -.05em; }
+.rating-count { font-size: .72rem; color: var(--text-3); }
+
+.product-pricing {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+  margin-top: auto;
+  padding-top: .6rem;
+}
+
+.price-current {
+  font-size: 1.05rem;
+  font-weight: 700;
+  color: var(--text-1);
+}
+.price-original {
+  font-size: .82rem;
+  color: var(--text-3);
+  text-decoration: line-through;
+}
+.price-discount {
+  font-size: .72rem;
+  font-weight: 700;
+  color: var(--green);
+  background: rgba(74,232,154,.1);
+  padding: .1rem .4rem;
+  border-radius: 99px;
+}
+
+.product-footer {
+  padding: 0 1.1rem 1.1rem;
+}
+
+.add-to-cart {
+  width: 100%;
+  background: var(--bg-hover);
+  border: 1px solid var(--border);
+  color: var(--text-1);
+  padding: .6rem;
+  border-radius: var(--radius-sm);
+  font-size: .82rem;
+  font-weight: 600;
+  transition: all var(--transition);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: .45rem;
+}
+.add-to-cart:hover {
+  background: var(--accent);
+  border-color: var(--accent);
+  color: #0d0d0f;
+}
+.add-to-cart.added {
+  background: rgba(74,232,154,.12);
+  border-color: var(--green);
+  color: var(--green);
+}
+
+/* ─── Deals Section ────────────────────────────────────────────── */
+.deals-section { background: var(--bg-surface); }
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 1.25rem;
+}
+
+@media (max-width: 900px) { .deals-grid { grid-template-columns: 1fr; } }
+
+.deal-card {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: grid;
+  grid-template-columns: auto 1fr;
+  gap: 1.5rem;
+  padding: 1.75rem;
+  align-items: center;
+  transition: all var(--transition);
+  position: relative;
+}
+.deal-card:hover { border-color: var(--text-3); transform: translateY(-2px); box-shadow: var(--shadow-card); }
+.deal-card.deal-featured {
+  grid-column: 1 / -1;
+  grid-template-columns: 1fr 1fr;
+  background: linear-gradient(135deg, var(--bg-card) 0%, rgba(232,193,74,.05) 100%);
+  border-color: rgba(232,193,74,.2);
+}
+
+.deal-img {
+  width: 110px;
+  height: 110px;
+  background: var(--bg-hover);
+  border-radius: var(--radius-md);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 3rem;
+  flex-shrink: 0;
+}
+.deal-featured .deal-img {
+  width: 100%;
+  height: 220px;
+  font-size: 5rem;
+}
+
+.deal-badge {
+  display: inline-flex;
+  align-items: center;
+  gap: .35rem;
+  background: rgba(232,84,84,.12);
+  color: var(--red);
+  border: 1px solid rgba(232,84,84,.25);
+  font-size: .72rem;
+  font-weight: 700;
+  letter-spacing: .06em;
+  text-transform: uppercase;
+  padding: .25rem .7rem;
+  border-radius: 99px;
+  margin-bottom: .6rem;
+}
+
+.deal-name {
+  font-size: 1.05rem;
+  font-weight: 700;
+  margin-bottom: .3rem;
+}
+.deal-featured .deal-name { font-size: 1.4rem; }
+
+.deal-desc {
+  font-size: .83rem;
+  color: var(--text-2);
+  margin-bottom: .75rem;
+}
+
+.deal-pricing {
+  display: flex;
+  align-items: baseline;
+  gap: .6rem;
+  margin-bottom: 1rem;
+}
+.deal-price-current { font-size: 1.4rem; font-weight: 800; color: var(--accent); }
+.deal-price-original { font-size: .88rem; color: var(--text-3); text-decoration: line-through; }
+
+.deal-timer {
+  display: flex;
+  gap: .5rem;
+  margin-bottom: 1.1rem;
+}
+
+.timer-block {
+  text-align: center;
+  background: var(--bg-hover);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  padding: .4rem .65rem;
+  min-width: 46px;
+}
+.timer-value {
+  font-size: 1.15rem;
+  font-weight: 800;
+  line-height: 1;
+  color: var(--text-1);
+  font-variant-numeric: tabular-nums;
+}
+.timer-label { font-size: .58rem; color: var(--text-3); text-transform: uppercase; letter-spacing: .06em; }
+
+.deal-progress-wrap {
+  margin-bottom: 1rem;
+}
+.deal-progress-label {
+  display: flex;
+  justify-content: space-between;
+  font-size: .72rem;
+  color: var(--text-3);
+  margin-bottom: .3rem;
+}
+.deal-progress-bar {
+  height: 5px;
+  background: var(--border);
+  border-radius: 99px;
+  overflow: hidden;
+}
+.deal-progress-fill {
+  height: 100%;
+  background: linear-gradient(90deg, var(--accent-dim), var(--accent));
+  border-radius: 99px;
+  transition: width 1s ease;
+}
+
+/* ─── Editorial / Content Section ─────────────────────────────── */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr;
+  gap: 1.25rem;
+}
+
+@media (max-width: 860px) { .editorial-grid { grid-template-columns: 1fr; } }
+
+.editorial-main {
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  position: relative;
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  min-height: 440px;
+  display: flex;
+  flex-direction: column;
+  justify-content: flex-end;
+  cursor: pointer;
+  transition: border-color var(--transition);
+}
+.editorial-main:hover { border-color: var(--text-3); }
+
+.editorial-bg {
+  position: absolute;
+  inset: 0;
+  font-size: 9rem;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460);
+  opacity: .7;
+  letter-spacing: -.05em;
+}
+
+.editorial-overlay {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to top, rgba(0,0,0,.85) 0%, transparent 55%);
+}
+
+.editorial-content {
+  position: relative;
+  padding: 2rem;
+}
+
+.editorial-tag {
+  display: inline-block;
+  background: var(--accent);
+  color: #0d0d0f;
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  padding: .25rem .7rem;
+  border-radius: 99px;
+  margin-bottom: .75rem;
+}
+
+.editorial-title {
+  font-size: 1.6rem;
+  font-weight: 800;
+  line-height: 1.2;
+  margin-bottom: .5rem;
+}
+
+.editorial-excerpt {
+  font-size: .88rem;
+  color: var(--text-2);
+  max-width: 50ch;
+  margin-bottom: 1.25rem;
+}
+
+.editorial-meta {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+  font-size: .78rem;
+  color: var(--text-3);
+}
+
+.editorial-side {
+  display: flex;
+  flex-direction: column;
+  gap: 1.25rem;
+}
+
+.editorial-small {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  padding: 1.25rem;
+  cursor: pointer;
+  transition: all var(--transition);
+  display: flex;
+  gap: 1rem;
+  align-items: center;
+  flex: 1;
+}
+.editorial-small:hover { border-color: var(--text-3); transform: translateX(3px); }
+
+.editorial-small-img {
+  width: 72px;
+  height: 72px;
+  background: var(--bg-hover);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 2rem;
+  flex-shrink: 0;
+}
+
+.editorial-small-tag {
+  font-size: .68rem;
+  font-weight: 700;
+  color: var(--accent);
+  text-transform: uppercase;
+  letter-spacing: .07em;
+  margin-bottom: .2rem;
+}
+.editorial-small-title {
+  font-size: .88rem;
+  font-weight: 600;
+  line-height: 1.35;
+  margin-bottom: .3rem;
+}
+.editorial-small-meta {
+  font-size: .72rem;
+  color: var(--text-3);
+}
+
+/* ─── Brand / Trust Banner ─────────────────────────────────────── */
+.brands-section {
+  background: var(--bg-surface);
+  padding-block: 3rem;
+}
+.brands-track {
+  overflow: hidden;
+  mask-image: linear-gradient(90deg, transparent, black 15%, black 85%, transparent);
+}
+.brands-inner {
+  display: flex;
+  gap: 3rem;
+  align-items: center;
+  animation: marquee 28s linear infinite;
+  width: max-content;
+}
+.brands-inner:hover { animation-play-state: paused; }
+.brand-item {
+  font-size: .85rem;
+  font-weight: 700;
+  letter-spacing: .12em;
+  text-transform: uppercase;
+  color: var(--text-3);
+  white-space: nowrap;
+  transition: color var(--transition);
+}
+.brand-item:hover { color: var(--text-2); }
+
+@keyframes marquee {
+  from { transform: translateX(0); }
+  to   { transform: translateX(-50%); }
+}
+
+/* ─── Trust Badges ─────────────────────────────────────────────── */
+.trust-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
+  gap: 1.25rem;
+  padding-block: 3rem;
+  border-top: 1px solid var(--border);
+}
+.trust-item {
+  display: flex;
+  align-items: center;
+  gap: .9rem;
+}
+.trust-icon {
+  width: 44px;
+  height: 44px;
+  background: var(--accent-glow);
+  border: 1px solid rgba(232,193,74,.2);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 1.2rem;
+  flex-shrink: 0;
+}
+.trust-title { font-size: .85rem; font-weight: 700; }
+.trust-sub   { font-size: .75rem; color: var(--text-3); }
+
+/* ─── Newsletter ───────────────────────────────────────────────── */
+.newsletter-section {
+  background: var(--bg-surface);
+  border-top: 1px solid var(--border);
+}
+
+.newsletter-box {
+  background: linear-gradient(135deg, var(--bg-card), rgba(232,193,74,.04));
+  border: 1px solid rgba(232,193,74,.15);
+  border-radius: var(--radius-lg);
+  padding: clamp(2rem, 5vw, 3.5rem);
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 2rem;
+  align-items: center;
+}
+
+@media (max-width: 700px) { .newsletter-box { grid-template-columns: 1fr; } }
+
+.newsletter-title {
+  font-size: 1.8rem;
+  font-weight: 800;
+  line-height: 1.2;
+  margin-bottom: .6rem;
+}
+.newsletter-sub { font-size: .9rem; color: var(--text-2); }
+
+.newsletter-form {
+  display: flex;
+  flex-direction: column;
+  gap: .75rem;
+}
+
+.newsletter-input-wrap {
+  display: flex;
+  background: var(--bg-hover);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  overflow: hidden;
+  transition: border-color var(--transition);
+}
+.newsletter-input-wrap:focus-within { border-color: var(--accent); }
+
+.newsletter-input {
+  flex: 1;
+  background: none;
+  border: none;
+  outline: none;
+  padding: .75rem 1rem;
+  font-size: .9rem;
+  color: var(--text-1);
+  font-family: inherit;
+}
+.newsletter-input::placeholder { color: var(--text-3); }
+
+.newsletter-btn {
+  padding: .75rem 1.25rem;
+  background: var(--accent);
+  color: #0d0d0f;
+  font-weight: 700;
+  font-size: .85rem;
+  border-left: 1px solid var(--border);
+  white-space: nowrap;
+  transition: background var(--transition);
+}
+.newsletter-btn:hover { background: #f0cc5a; }
+
+.newsletter-disclaimer { font-size: .72rem; color: var(--text-3); }
+
+/* ─── Footer ───────────────────────────────────────────────────── */
+.footer {
+  background: var(--bg-surface);
+  border-top: 1px solid var(--border);
+  padding-block: 3.5rem 2rem;
+}
+
+.footer-grid {
+  display: grid;
+  grid-template-columns: 2fr repeat(3, 1fr);
+  gap: 3rem;
+  margin-bottom: 3rem;
+}
+
+@media (max-width: 820px) {
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+}
+
+.footer-brand p {
+  font-size: .85rem;
+  color: var(--text-2);
+  margin-top: .7rem;
+  max-width: 30ch;
+  line-height: 1.7;
+}
+
+.footer-social {
+  display: flex;
+  gap: .5rem;
+  margin-top: 1.25rem;
+}
+.social-btn {
+  width: 34px;
+  height: 34px;
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--text-3);
+  font-size: .85rem;
+  transition: all var(--transition);
+}
+.social-btn:hover { border-color: var(--accent); color: var(--accent); }
+
+.footer-col-title {
+  font-size: .8rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .1em;
+  color: var(--text-1);
+  margin-bottom: 1rem;
+}
+.footer-links { display: flex; flex-direction: column; gap: .55rem; }
+.footer-links a {
+  font-size: .85rem;
+  color: var(--text-3);
+  transition: color var(--transition);
+}
+.footer-links a:hover { color: var(--text-1); }
+
+.footer-bottom {
+  border-top: 1px solid var(--border);
+  padding-top: 1.5rem;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: .75rem;
+  font-size: .78rem;
+  color: var(--text-3);
+}
+
+.footer-payments {
+  display: flex;
+  gap: .45rem;
+  align-items: center;
+}
+.payment-chip {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  padding: .2rem .55rem;
+  font-size: .65rem;
+  font-weight: 700;
+  letter-spacing: .04em;
+  color: var(--text-2);
+}
+
+/* ─── Utility / Toast ──────────────────────────────────────────── */
+.toast {
+  position: fixed;
+  bottom: 1.5rem;
+  right: 1.5rem;
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  padding: .85rem 1.25rem;
+  display: flex;
+  align-items: center;
+  gap: .75rem;
+  font-size: .85rem;
+  font-weight: 500;
+  box-shadow: var(--shadow-card);
+  z-index: 999;
+  transform: translateY(120%);
+  opacity: 0;
+  transition: all .35s cubic-bezier(.34,1.56,.64,1);
+}
+.toast.show { transform: translateY(0); opacity: 1; }
+.toast-icon { font-size: 1.1rem; }
