*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:    #0d0d0f;
  --bg-surface: #16161a;
  --bg-card:    #1e1e24;
  --bg-hover:   #26262e;
  --border:     #2e2e38;
  --accent:     #e8c14a;
  --accent-dim: #b8952e;
  --accent-glow:rgba(232,193,74,.18);
  --red:        #e85454;
  --green:      #4ae89a;
  --text-1:     #f0f0f4;
  --text-2:     #a8a8b8;
  --text-3:     #606070;
  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  20px;
  --shadow-card:0 4px 24px rgba(0,0,0,.55);
  --transition: .2s cubic-bezier(.4,0,.2,1);
  --max-w:      1280px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, sans-serif;
  background: var(--bg-base);
  color: var(--text-1);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

.container {
  width: min(100%, var(--max-w));
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2.5rem);
}

/* ─── Scrollbar ────────────────────────────────────────────────── */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg-base); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 99px; }

/* ─── Announcement Bar ─────────────────────────────────────────── */
.announcement-bar {
  background: var(--accent);
  color: #0d0d0f;
  text-align: center;
  font-size: .8rem;
  font-weight: 600;
  letter-spacing: .05em;
  padding: .45rem 1rem;
}

/* ─── Navigation ───────────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.88);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 64px;
}

.nav-logo {
  font-size: 1.3rem;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--text-1);
  white-space: nowrap;
  flex-shrink: 0;
}
.nav-logo span { color: var(--accent); }

.nav-links {
  display: flex;
  gap: 1.6rem;
  font-size: .88rem;
  font-weight: 500;
}

.nav-links a {
  color: var(--text-2);
  transition: color var(--transition);
}
.nav-links a:hover { color: var(--text-1); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: .75rem;
  margin-left: auto;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: .5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: .35rem .75rem;
  font-size: .85rem;
  color: var(--text-3);
  transition: border-color var(--transition);
  width: 200px;
}
.nav-search:hover { border-color: var(--text-3); }
.nav-search svg { flex-shrink: 0; }

.nav-icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  color: var(--text-2);
  transition: background var(--transition), color var(--transition);
}
.nav-icon-btn:hover { background: var(--bg-card); color: var(--text-1); }

.cart-badge {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 16px;
  height: 16px;
  background: var(--accent);
  color: #0d0d0f;
  font-size: .6rem;
  font-weight: 700;
  border-radius: 50%;
  display: grid;
  place-items: center;
}

.nav-mobile-toggle {
  display: none;
  color: var(--text-2);
  padding: .4rem;
}

/* ─── Hero ─────────────────────────────────────────────────────── */
.hero {
  position: relative;
  overflow: hidden;
  min-height: 580px;
  display: flex;
  align-items: center;
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 60% at 70% 50%, rgba(232,193,74,.08) 0%, transparent 70%),
    radial-gradient(ellipse 40% 80% at 20% 80%, rgba(100,100,255,.06) 0%, transparent 60%);
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 48px 48px;
  opacity: .25;
  mask-image: radial-gradient(ellipse 70% 70% at 50% 50%, black 40%, transparent 100%);
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  padding-block: 5rem;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .45rem;
  font-size: .78rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--accent-glow);
  border: 1px solid rgba(232,193,74,.28);
  border-radius: 99px;
  padding: .3rem .85rem;
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1.1rem;
}
.hero-title span { color: var(--accent); }

.hero-sub {
  font-size: 1.05rem;
  color: var(--text-2);
  max-width: 44ch;
  margin-bottom: 2rem;
}

.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .45rem;
  padding: .7rem 1.5rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 600;
  transition: all var(--transition);
}
.btn-primary {
  background: var(--accent);
  color: #0d0d0f;
}
.btn-primary:hover { background: #f0cc5a; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(232,193,74,.35); }

.btn-outline {
  border: 1px solid var(--border);
  color: var(--text-1);
  background: var(--bg-card);
}
.btn-outline:hover { border-color: var(--text-3); background: var(--bg-hover); }

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
}

.hero-stat-value {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--text-1);
}
.hero-stat-label {
  font-size: .78rem;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: .06em;
}

.hero-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: .85rem;
}

.hero-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: .6rem;
  transition: border-color var(--transition), transform var(--transition);
}
.hero-card:hover { border-color: var(--text-3); transform: translateY(-2px); }
.hero-card.featured { grid-column: 1 / -1; flex-direction: row; align-items: center; gap: 1.25rem; }

.hero-card-img {
  width: 100%;
  aspect-ratio: 1;
  background: var(--bg-hover);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.4rem;
  flex-shrink: 0;
}
.hero-card.featured .hero-card-img { width: 80px; height: 80px; aspect-ratio: auto; font-size: 2rem; }

.hero-card-name { font-size: .82rem; font-weight: 600; }
.hero-card-price { font-size: .9rem; font-weight: 700; color: var(--accent); }
.hero-card-rating { font-size: .72rem; color: var(--text-3); }

/* ─── Section Scaffolding ──────────────────────────────────────── */
.section { padding-block: 5rem; }
.section + .section { border-top: 1px solid var(--border); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2.25rem;
  gap: 1rem;
  flex-wrap: wrap;
}

.section-label {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .35rem;
}

.section-title {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -.02em;
}

.section-sub {
  font-size: .9rem;
  color: var(--text-2);
  margin-top: .3rem;
}

.view-all {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  font-size: .85rem;
  font-weight: 600;
  color: var(--accent);
  white-space: nowrap;
  transition: gap var(--transition);
}
.view-all:hover { gap: .6rem; }

/* ─── Categories ───────────────────────────────────────────────── */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: .85rem;
}

.category-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 1.4rem 1rem;
  text-align: center;
  cursor: pointer;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .7rem;
}
.category-card:hover {
  border-color: var(--accent);
  background: var(--bg-hover);
  transform: translateY(-2px);
}

.category-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-sm);
  background: var(--bg-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.6rem;
  transition: background var(--transition);
}
.category-card:hover .category-icon { background: var(--accent-glow); }

.category-name {
  font-size: .8rem;
  font-weight: 600;
  color: var(--text-2);
}
.category-count {
  font-size: .7rem;
  color: var(--text-3);
}

/* ─── Product Grid ─────────────────────────────────────────────── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
  position: relative;
}
.product-card:hover {
  border-color: var(--text-3);
  transform: translateY(-3px);
  box-shadow: var(--shadow-card);
}

.product-img {
  aspect-ratio: 1 / 1;
  background: var(--bg-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  position: relative;
  overflow: hidden;
}

.product-badges {
  position: absolute;
  top: .75rem;
  left: .75rem;
  display: flex;
  flex-direction: column;
  gap: .35rem;
}

.badge {
  font-size: .68rem;
  font-weight: 700;
  letter-spacing: .04em;
  padding: .2rem .55rem;
  border-radius: 99px;
  text-transform: uppercase;
}
.badge-new    { background: #4a90e8; color: #fff; }
.badge-sale   { background: var(--red); color: #fff; }
.badge-hot    { background: #e87a4a; color: #fff; }
.badge-sold   { background: var(--text-3); color: var(--bg-base); }

.product-wishlist {
  position: absolute;
  top: .75rem;
  right: .75rem;
  width: 32px;
  height: 32px;
  background: rgba(13,13,15,.7);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-3);
  transition: all var(--transition);
  opacity: 0;
}
.product-card:hover .product-wishlist { opacity: 1; }
.product-wishlist:hover { color: var(--red); background: rgba(232,84,84,.15); }
.product-wishlist.active { opacity: 1; color: var(--red); }

.product-body {
  padding: 1rem 1.1rem 1.2rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: .35rem;
}

.product-brand {
  font-size: .7rem;
  font-weight: 600;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: .06em;
}

.product-name {
  font-size: .9rem;
  font-weight: 600;
  color: var(--text-1);
  line-height: 1.4;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  margin-top: .1rem;
}
.stars { color: var(--accent); font-size: .78rem; letter-spacing: -.05em; }
.rating-count { font-size: .72rem; color: var(--text-3); }

.product-pricing {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  margin-top: auto;
  padding-top: .6rem;
}

.price-current {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-1);
}
.price-original {
  font-size: .82rem;
  color: var(--text-3);
  text-decoration: line-through;
}
.price-discount {
  font-size: .72rem;
  font-weight: 700;
  color: var(--green);
  background: rgba(74,232,154,.1);
  padding: .1rem .4rem;
  border-radius: 99px;
}

.product-footer {
  padding: 0 1.1rem 1.1rem;
}

.add-to-cart {
  width: 100%;
  background: var(--bg-hover);
  border: 1px solid var(--border);
  color: var(--text-1);
  padding: .6rem;
  border-radius: var(--radius-sm);
  font-size: .82rem;
  font-weight: 600;
  transition: all var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .45rem;
}
.add-to-cart:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: #0d0d0f;
}
.add-to-cart.added {
  background: rgba(74,232,154,.12);
  border-color: var(--green);
  color: var(--green);
}

/* ─── Deals Section ────────────────────────────────────────────── */
.deals-section { background: var(--bg-surface); }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
}

@media (max-width: 900px) { .deals-grid { grid-template-columns: 1fr; } }

.deal-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 1.5rem;
  padding: 1.75rem;
  align-items: center;
  transition: all var(--transition);
  position: relative;
}
.deal-card:hover { border-color: var(--text-3); transform: translateY(-2px); box-shadow: var(--shadow-card); }
.deal-card.deal-featured {
  grid-column: 1 / -1;
  grid-template-columns: 1fr 1fr;
  background: linear-gradient(135deg, var(--bg-card) 0%, rgba(232,193,74,.05) 100%);
  border-color: rgba(232,193,74,.2);
}

.deal-img {
  width: 110px;
  height: 110px;
  background: var(--bg-hover);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  flex-shrink: 0;
}
.deal-featured .deal-img {
  width: 100%;
  height: 220px;
  font-size: 5rem;
}

.deal-badge {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  background: rgba(232,84,84,.12);
  color: var(--red);
  border: 1px solid rgba(232,84,84,.25);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .25rem .7rem;
  border-radius: 99px;
  margin-bottom: .6rem;
}

.deal-name {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: .3rem;
}
.deal-featured .deal-name { font-size: 1.4rem; }

.deal-desc {
  font-size: .83rem;
  color: var(--text-2);
  margin-bottom: .75rem;
}

.deal-pricing {
  display: flex;
  align-items: baseline;
  gap: .6rem;
  margin-bottom: 1rem;
}
.deal-price-current { font-size: 1.4rem; font-weight: 800; color: var(--accent); }
.deal-price-original { font-size: .88rem; color: var(--text-3); text-decoration: line-through; }

.deal-timer {
  display: flex;
  gap: .5rem;
  margin-bottom: 1.1rem;
}

.timer-block {
  text-align: center;
  background: var(--bg-hover);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: .4rem .65rem;
  min-width: 46px;
}
.timer-value {
  font-size: 1.15rem;
  font-weight: 800;
  line-height: 1;
  color: var(--text-1);
  font-variant-numeric: tabular-nums;
}
.timer-label { font-size: .58rem; color: var(--text-3); text-transform: uppercase; letter-spacing: .06em; }

.deal-progress-wrap {
  margin-bottom: 1rem;
}
.deal-progress-label {
  display: flex;
  justify-content: space-between;
  font-size: .72rem;
  color: var(--text-3);
  margin-bottom: .3rem;
}
.deal-progress-bar {
  height: 5px;
  background: var(--border);
  border-radius: 99px;
  overflow: hidden;
}
.deal-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-dim), var(--accent));
  border-radius: 99px;
  transition: width 1s ease;
}

/* ─── Editorial / Content Section ─────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 1.25rem;
}

@media (max-width: 860px) { .editorial-grid { grid-template-columns: 1fr; } }

.editorial-main {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  background: var(--bg-card);
  border: 1px solid var(--border);
  min-height: 440px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  cursor: pointer;
  transition: border-color var(--transition);
}
.editorial-main:hover { border-color: var(--text-3); }

.editorial-bg {
  position: absolute;
  inset: 0;
  font-size: 9rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460);
  opacity: .7;
  letter-spacing: -.05em;
}

.editorial-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.85) 0%, transparent 55%);
}

.editorial-content {
  position: relative;
  padding: 2rem;
}

.editorial-tag {
  display: inline-block;
  background: var(--accent);
  color: #0d0d0f;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: .25rem .7rem;
  border-radius: 99px;
  margin-bottom: .75rem;
}

.editorial-title {
  font-size: 1.6rem;
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: .5rem;
}

.editorial-excerpt {
  font-size: .88rem;
  color: var(--text-2);
  max-width: 50ch;
  margin-bottom: 1.25rem;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: .78rem;
  color: var(--text-3);
}

.editorial-side {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.editorial-small {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  cursor: pointer;
  transition: all var(--transition);
  display: flex;
  gap: 1rem;
  align-items: center;
  flex: 1;
}
.editorial-small:hover { border-color: var(--text-3); transform: translateX(3px); }

.editorial-small-img {
  width: 72px;
  height: 72px;
  background: var(--bg-hover);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  flex-shrink: 0;
}

.editorial-small-tag {
  font-size: .68rem;
  font-weight: 700;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: .07em;
  margin-bottom: .2rem;
}
.editorial-small-title {
  font-size: .88rem;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: .3rem;
}
.editorial-small-meta {
