.footer-links { display: flex; flex-direction: column; gap: .55rem; }
.footer-links a {
  font-size: .85rem;
  color: var(--text-3);
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--text-1); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: .75rem;
  font-size: .78rem;
  color: var(--text-3);
}

.footer-payments {
  display: flex;
  gap: .45rem;
