}
.payment-chip {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: .2rem .55rem;
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .04em;
  color: var(--text-2);
}

/* ─── Utility / Toast ──────────────────────────────────────────── */
.toast {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
