/* ── Data ── */
const products = [
  { id:1,  brand:'Sony',      name:'WH-1000XM5 Wireless Headphones', price:279, original:349, rating:4.8, reviews:2104, emoji:'🎧', badge:'sale',  category:'electronics' },
  { id:2,  brand:'Apple',     name:'MagSafe Charger 15W',            price:39,  original:null,rating:4.6, reviews:880,  emoji:'🔌', badge:'new',   category:'electronics' },
  { id:3,  brand:'Nike',      name:'Air Max 270 React Sneakers',     price:149, original:180, rating:4.7, reviews:3300, emoji:'👟', badge:'hot',   category:'fashion' },
  { id:4,  brand:'Dyson',     name:'V15 Detect Cordless Vacuum',     price:599, original:699, rating:4.9, reviews:1540, emoji:'🌀', badge:'sale',  category:'home' },
  { id:5,  brand:'Levi\'s',   name:'501 Original Fit Jeans',         price:69,  original:null,rating:4.5, reviews:6700, emoji:'👖', badge:null,    category:'fashion' },
  { id:6,  brand:'KitchenAid',name:'Stand Mixer 5-Qt Artisan',       price:349, original:449, rating:4.8, reviews:990,  emoji:'🍰', badge:'sale',  category:'home' },
  { id:7,  brand:'Samsung',   name:'55" QLED 4K Smart TV',           price:799, original:999, rating:4.6, reviews:2210, emoji:'📺', badge:'hot',   category:'electronics' },
  { id:8,  brand:'Adidas',    name:'Ultraboost 22 Running Shoes',    price:129, original:160, rating:4.7, reviews:4100, emoji:'🏃', badge:'new',   category:'fashion' },
];

const deals = [
  {
    featured: true,
    emoji: '💻',
    tag: '🔥 Deal of the Day',
    name: 'MacBook Air M2 — 13"',
    desc: 'Apple Silicon. All-day battery life. Fanless design for silent performance anywhere.',
    price: 999,
    original: 1299,
    discount: 23,
    sold: 78,
    total: 100,
