  },
  {
    featured: false,
    emoji: '📷',
    tag: '⚡ Flash Sale',
    name: 'Canon EOS R50 Mirrorless',
    desc: 'Content-creator camera with 4K video & Eye AF.',
    price: 649,
    original: 899,
    discount: 28,
    sold: 62,
    total: 80,
    hours: 2, mins: 15, secs: 8,
  },
  {
    featured: false,
    emoji: '🎮',
    tag: '🎯 Limited Offer',
    name: 'PlayStation 5 Bundle',
    desc: 'PS5 console + 2 controllers + 3 hit games.',
    price: 499,
    original: 649,
    discount: 23,
    sold: 91,
    total: 100,
    hours: 0, mins: 38, secs: 55,
  },
];

const editorials = [
  {
    main: true,
    tag: 'Style Guide',
    emoji: '🕶️',
    title: 'Summer 2026: The Looks Defining the Season',
    excerpt: 'From minimalist coastal to bold maximalism — our editors break down the trends worth investing in this summer.',
    author: 'Maya Okoye',
    readTime: '6 min read',
    date: 'May 4, 2026',
  },
  {
    tag: 'Tech Review',
    emoji: '⌚',
    title: 'Best Smartwatches of 2026',
    date: 'Apr 28',
    readTime: '4 min',
  },
  {
    tag: 'Home & Living',
    emoji: '🪴',
