];

/* ── Helpers ── */
const $ = id => document.getElementById(id);
const el = (tag, cls, html='') => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html) e.innerHTML = html;
  return e;
};

function stars(n) {
  return '★'.repeat(Math.floor(n)) + (n % 1 >= .5 ? '½' : '') + '☆'.repeat(5 - Math.ceil(n));
}

function fmt(n) {
  return '$' + n.toLocaleString('en-US', { minimumFractionDigits: 0 });
}

/* ── Wishlist state ── */
const wishlist = new Set();
let cartCount = 0;

function updateCartBadge() {
  const badge = document.querySelector('.cart-badge');
  if (badge) badge.textContent = cartCount;
}

/* ── Toast ── */
let toastTimer;
function showToast(icon, msg) {
  const toast = $('toast');
  toast.querySelector('.toast-icon').textContent = icon;
  toast.querySelector('.toast-msg').textContent  = msg;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 2800);
}

/* ── Build Products ── */
function buildProducts() {
  const grid = $('products-grid');
  products.forEach(p => {
    const card = el('div', 'product-card');
    const badgeHtml = p.badge
      ? `<div class="product-badges"><span class="badge badge-${p.badge}">${p.badge}</span></div>`
      : '';
    const origHtml = p.original
      ? `<span class="price-original">${fmt(p.original)}</span>
         <span class="price-discount">-${Math.round((1-p.price/p.original)*100)}%</span>`
      : '';

    card.innerHTML = `
      <div class="product-img">
        <span>${p.emoji}</span>
        ${badgeHtml}
        <button class="product-wishlist" data-id="${p.id}" aria-label="Wishlist">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2">
            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
          </svg>
        </button>
      </div>
      <div class="product-body">
        <div class="product-brand">${p.brand}</div>
        <div class="product-name">${p.name}</div>
        <div class="product-rating">
          <span class="stars">${stars(p.rating)}</span>
          <span class="rating-count">${p.rating} (${p.reviews.toLocaleString()})</span>
        </div>
        <div class="product-pricing">
          <span class="price-current">${fmt(p.price)}</span>
          ${origHtml}
        </div>
      </div>
      <div class="product-footer">
        <button class="add-to-cart" data-id="${p.id}">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2">
            <circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/>
            <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/>
          </svg>
          Add to Cart
        </button>
      </div>
    `;
    grid.appendChild(card);
  });

  /* wishlist clicks */
  grid.querySelectorAll('.product-wishlist').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const id = +btn.dataset.id;
      if (wishlist.has(id)) {
        wishlist.delete(id);
        btn.classList.remove('active');
        showToast('💔', 'Removed from wishlist');
      } else {
        wishlist.add(id);
        btn.classList.add('active');
        showToast('❤️', 'Added to wishlist!');
      }
    });
  });

  /* add-to-cart clicks */
  grid.querySelectorAll('.add-to-cart').forEach(btn => {
