];

/* ── Helpers ── */
const $ = id => document.getElementById(id);
const el = (tag, cls, html='') => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html) e.innerHTML = html;
  return e;
};

function stars(n) {
  return '★'.repeat(Math.floor(n)) + (n % 1 >= .5 ? '½' : '') + '☆'.repeat(5 - Math.ceil(n));
}

function fmt(n) {
  return '$' + n.toLocaleString('en-US', { minimumFractionDigits: 0 });
}

/* ── Wishlist state ── */
const wishlist = new Set();
let cartCount = 0;

function updateCartBadge() {
  const badge = document.querySelector('.cart-badge');
  if (badge) badge.textContent = cartCount;
}

/* ── Toast ── */
let toastTimer;
function showToast(icon, msg) {
  const toast = $('toast');
  toast.querySelector('.toast-icon').textContent = icon;
  toast.querySelector('.toast-msg').textContent  = msg;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 2800);
}

/* ── Build Products ── */
function buildProducts() {
  const grid = $('products-grid');
  products.forEach(p => {
    const card = el('div', 'product-card');
    const badgeHtml = p.badge
      ? `<div class="product-badges"><span class="badge badge-${p.badge}">${p.badge}</span></div>`
      : '';
    const origHtml = p.original
      ? `<span class="price-original">${fmt(p.original)}</span>
         <span class="price-discount">-${Math.round((1-p.price/p.original)*100)}%</span>`
      : '';

    card.innerHTML = `
      <div class="product-img">
        <span>${p.emoji}</span>
        ${badgeHtml}
        <button class="product-wishlist" data-id="${p.id}" aria-label="Wishlist">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2">
            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
          </svg>
        </button>
      </div>
      <div class="product-body">
        <div class="product-brand">${p.brand}</div>
        <div class="product-name">${p.name}</div>
        <div class="product-rating">
          <span class="stars">${stars(p.rating)}</span>
          <span class="rating-count">${p.rating} (${p.reviews.toLocaleString()})</span>
        </div>
        <div class="product-pricing">
          <span class="price-current">${fmt(p.price)}</span>
          ${origHtml}
        </div>
      </div>
      <div class="product-footer">
        <button class="add-to-cart" data-id="${p.id}">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2">
            <circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/>
            <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/>
          </svg>
          Add to Cart
        </button>
      </div>
    `;
    grid.appendChild(card);
  });

  /* wishlist clicks */
  grid.querySelectorAll('.product-wishlist').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const id = +btn.dataset.id;
      if (wishlist.has(id)) {
        wishlist.delete(id);
        btn.classList.remove('active');
        showToast('💔', 'Removed from wishlist');
      } else {
        wishlist.add(id);
        btn.classList.add('active');
        showToast('❤️', 'Added to wishlist!');
      }
    });
  });

  /* add-to-cart clicks */
  grid.querySelectorAll('.add-to-cart').forEach(btn => {
    btn.addEventListener('click', () => {
      const id = +btn.dataset.id;
      const product = products.find(p => p.id === id);
      cartCount++;
      updateCartBadge();
      btn.classList.add('added');
      btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg> Added!`;
      showToast('🛒', `${product.name} added to cart!`);
      setTimeout(() => {
        btn.classList.remove('added');
        btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg> Add to Cart`;
      }, 1800);
    });
  });
}

/* ── Build Deals ── */
function buildDeals() {
  const grid = $('deals-grid');

  deals.forEach((d, i) => {
    const card = el('div', `deal-card${d.featured ? ' deal-featured' : ''}`);
    const timerId = `timer-${i}`;

    const timerHtml = `
      <div class="deal-timer" id="${timerId}" data-h="${d.hours}" data-m="${d.mins}" data-s="${d.secs}">
        <div class="timer-block"><div class="timer-value t-h">${String(d.hours).padStart(2,'0')}</div><div class="timer-label">hrs</div></div>
        <div class="timer-block"><div class="timer-value t-m">${String(d.mins).padStart(2,'0')}</div><div class="timer-label">min</div></div>
        <div class="timer-block"><div class="timer-value t-s">${String(d.secs).padStart(2,'0')}</div><div class="timer-label">sec</div></div>
      </div>`;

    const pct = Math.round((d.sold / d.total) * 100);
    const progressHtml = `
      <div class="deal-progress-wrap">
        <div class="deal-progress-label"><span>Sold: ${d.sold}/${d.total}</span><span>${pct}% gone</span></div>
        <div class="deal-progress-bar"><div class="deal-progress-fill" style="width:${pct}%"></div></div>
      </div>`;

    card.innerHTML = `
      <div class="deal-img">${d.emoji}</div>
      <div class="deal-body">
        <div class="deal-badge">${d.tag}</div>
        <div class="deal-name">${d.name}</div>
        <div class="deal-desc">${d.desc}</div>
        <div class="deal-pricing">
          <span class="deal-price-current">${fmt(d.price)}</span>
          <span class="deal-price-original">${fmt(d.original)}</span>
          <span class="price-discount">-${d.discount}%</span>
        </div>
        ${timerHtml}
        ${progressHtml}
        <button class="btn btn-primary deal-btn">Grab This Deal</button>
      </div>
    `;
    grid.appendChild(card);

    card.querySelector('.deal-btn').addEventListener('click', () => {
      cartCount++;
      updateCartBadge();
      showToast('🔥', `${d.name} added to cart!`);
    });
  });

  startTimers();
}

/* ── Countdown Timers ── */
function startTimers() {
  const timers = document.querySelectorAll('.deal-timer');
  timers.forEach(t => {
    let h = +t.dataset.h, m = +t.dataset.m, s = +t.dataset.s;
    setInterval(() => {
      s--;
      if (s < 0) { s = 59; m--; }
      if (m < 0) { m = 59; h--; }
      if (h < 0) { h = m = s = 0; }
      t.querySelector('.t-h').textContent = String(h).padStart(2,'0');
      t.querySelector('.t-m').textContent = String(m).padStart(2,'0');
      t.querySelector('.t-s').textContent = String(s).padStart(2,'0');
    }, 1000);
  });
}

/* ── Build Categories ── */
function buildCategories() {
  const grid = $('categories-grid');
  categories.forEach(c => {
    const card = el('div', 'category-card');
    card.innerHTML = `
      <div class="category-icon">${c.emoji}</div>
      <div class="category-name">${c.name}</div>
      <div class="category-count">${c.count} items</div>
    `;
    card.addEventListener('click', () => showToast('🔍', `Browsing ${c.name}…`));
    grid.appendChild(card);
  });
}

/* ── Build Editorial ── */
function buildEditorial() {
  const main = editorials.find(e => e.main);
  const side = editorials.filter(e => !e.main);

  const mainEl = $('editorial-main');
  mainEl.innerHTML = `
    <div class="editorial-bg">${main.emoji}</div>
    <div class="editorial-overlay"></div>
    <div class="editorial-content">
      <span class="editorial-tag">${main.tag}</span>
      <h3 class="editorial-title">${main.title}</h3>
      <p class="editorial-excerpt">${main.excerpt}</p>
      <div class="editorial-meta">
        <span>✍️ ${main.author}</span>
        <span>⏱ ${main.readTime}</span>
        <span>📅 ${main.date}</span>
      </div>
    </div>
  `;

  const sideEl = $('editorial-side');
  side.forEach(s => {
    const card = el('div', 'editorial-small');
    card.innerHTML = `
      <div class="editorial-small-img">${s.emoji}</div>
      <div>
        <div class="editorial-small-tag">${s.tag}</div>
        <div class="editorial-small-title">${s.title}</div>
        <div class="editorial-small-meta">${s.date} · ${s.readTime}</div>
      </div>
    `;
    sideEl.appendChild(card);
  });
}

/* ── Newsletter Form ── */
function initNewsletter() {
  const form = $('newsletter-form');
  form.addEventListener('submit', e => {
    e.preventDefault();
    const input = form.querySelector('.newsletter-input');
    if (input.value.trim()) {
      showToast('✉️', 'You\'re subscribed! Check your inbox.');
      input.value = '';
    }
  });
}

/* ── Mobile Nav ── */
function initMobileNav() {
  const toggle = $('mobile-toggle');
  const links  = $('nav-links');
  toggle.addEventListener('click', () => {
    const open = links.style.display === 'flex';
    links.style.display = open ? '' : 'flex';
    links.style.flexDirection = 'column';
    links.style.position = 'absolute';
    links.style.top = '64px';
    links.style.left = '0';
    links.style.right = '0';
    links.style.background = 'var(--bg-surface)';
    links.style.borderBottom = '1px solid var(--border)';
    links.style.padding = open ? '' : '1rem 2rem';
    links.style.gap = '1rem';
    links.style.zIndex = '99';
  });
}

/* ── Scroll Reveal ── */
function initScrollReveal() {
  const style = document.createElement('style');
  style.textContent = `
    .reveal { opacity:0; transform:translateY(22px); transition:opacity .55s ease, transform .55s ease; }
    .reveal.visible { opacity:1; transform:none; }
  `;
  document.head.appendChild(style);

  document.querySelectorAll(
    '.product-card, .deal-card, .category-card, .editorial-main, .editorial-small, .trust-item'
  ).forEach((el, i) => {
    el.classList.add('reveal');
    el.style.transitionDelay = `${(i % 6) * 55}ms`;
  });

  const io = new IntersectionObserver(entries => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('visible'); io.unobserve(e.target); } });
  }, { threshold: 0.08 });

  document.querySelectorAll('.reveal').forEach(el => io.observe(el));
}

/* ── Init ── */
document.addEventListener('DOMContentLoaded', () => {
  buildCategories();
  buildProducts();
  buildDeals();
  buildEditorial();
  initNewsletter();
  initMobileNav();
  initScrollReveal();
});
